mapper.select:
SELECT c.card_id AS cardId, c.card_name AS cardName, co.company_name AS cardCompanyName, COALESCE(MIN(f.total_fee), 0) AS minAnnualFee FROM card c JOIN card_company co ON co.card_company_id = c.card_company_id LEFT JOIN card_annual_fee f ON f.card_id = c.card_id WHERE c.card_id IN
#{cardId}
GROUP BY c.card_id, c.card_name, co.company_name
